  function renderPage(){const map={dashboard:renderDashboard,appointments:renderAppointments,clients:renderClients,services:renderServices,staff:renderStaff,inventory:renderInventory,pos:renderPos,commissions:renderCommissions,facilities:renderFacilities,reports:renderReports,settings:renderSettings};document.getElementById("slContent").innerHTML=(map[page]||renderDashboard)();bindPage()}
  function bindPage(){
    document.querySelectorAll("[data-open-form]").forEach(button=>button.addEventListener("click",()=>{feedback();openForm(button.dataset.openForm)}));
    document.querySelectorAll("[data-edit-type]").forEach(button=>button.addEventListener("click",()=>openForm(button.dataset.editType,button.dataset.editId)));
    document.querySelectorAll("[data-delete-type]").forEach(button=>button.addEventListener("click",()=>confirmDelete(button.dataset.deleteType,button.dataset.deleteId)));
    const search=document.getElementById("slSearch");if(search)search.addEventListener("input",()=>{filters.search=search.value;renderPage()});
    const status=document.getElementById("slStatus");if(status)status.addEventListener("change",()=>{filters.status=status.value;renderPage()});
    document.querySelectorAll("[data-add-service]").forEach(button=>button.addEventListener("click",()=>addToCart(button.dataset.addService)));
    document.querySelectorAll("[data-remove-cart]").forEach(button=>button.addEventListener("click",()=>removeFromCart(button.dataset.removeCart)));
    const complete=document.getElementById("slCompleteSale");if(complete)complete.addEventListener("click",completeSale);
    const settingsForm=document.getElementById("slSettingsForm");if(settingsForm)settingsForm.addEventListener("submit",saveSettings);
    document.querySelectorAll("[data-setting-toggle]").forEach(button=>button.addEventListener("click",()=>{const key=button.dataset.settingToggle;data.settings[key]=!data.settings[key];save();renderPage();toast(t("تم تحديث التنبيهات","Alerts updated"))}));
    const settingLanguage=document.getElementById("slSettingLanguage");if(settingLanguage)settingLanguage.addEventListener("click",()=>setLanguage(language==="ar"?"en":"ar"));
    const changeType=document.getElementById("slChangeType");if(changeType)changeType.addEventListener("click",()=>location.href="./salons.html?change=1");
    const exp=document.getElementById("slExport");if(exp)exp.addEventListener("click",exportData);
    const reset=document.getElementById("slReset");if(reset)reset.addEventListener("click",()=>openConfirm(t("إعادة البيانات التجريبية؟","Restore demo data?"),t("سيتم استبدال بيانات هذا الصالون بالنسخة التجريبية.","This salon’s current data will be replaced with demo data."),()=>{data=seed();save();renderPage();toast(t("تمت إعادة البيانات التجريبية","Demo data restored"))}));
  }

